cypress_script:
describe('Broken Images Page Accessibility', () => {
  it('should display the page title and heading', () => {
    cy.visit('https://the-internet.herokuapp.com/broken_images');
    cy.title().should('eq', 'The Internet');
    cy.get('h1').should('have.text', 'Broken Images');
  });

  it('should not display any valid images', () => {
    cy.visit('https://the-internet.herokuapp.com/broken_images');
    cy.get('#content').within(() => {
      cy.get('img').should('have.length', 2);
      cy.get('img').each(($img) => {
        cy.wrap($img).should('have.attr', 'src').and('match', /broken-image/);
      });
    });
  });
});

playwright_script:
import { test, expect } from '@playwright/test';
test.describe('Broken Images Page Accessibility', () => {
  test('should display the page title and heading', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/broken_images');
    expect(await page.title()).toBe('The Internet');
    const heading = await page.locator('h1');
    await expect(heading).toHaveText('Broken Images');
  });

  test('should not display any valid images', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/broken_images');
    const images = await page.locator('#content img');
    expect(await images.count()).toBe(2);
    for (let i = 0; i < await images.count(); i++) {
      const src = await images.nth(i).getAttribute('src');
      expect(src).toMatch(/broken-image/);
    }
  });
});
